const triggers = $json.result || [];
const scriptId = parseInt($env.ZABBIX_SCRIPT_ID);
const items    = [];

for (const trigger of triggers) {
  const host = trigger.hosts?.[0];
  const item = trigger.items?.[0];
  if (!host || !item) continue;

  const keyMatch = item.key_.match(/^service\.info\[([^,]+)/);
  if (!keyMatch) continue;

  const hostid = parseInt(host.hostid);
  let serviceName = keyMatch[1];
  // Remove aspas ao redor do nome (ex: "cloudbase-init" -> cloudbase-init)
  if (serviceName.charCodeAt(0) === 34) serviceName = serviceName.slice(1, -1);

  items.push({
    json: {
      hostname:     host.host,
      service_name: serviceName,
      execute_body: JSON.stringify({
        jsonrpc: '2.0',
        method:  'script.execute',
        params:  { scriptid: scriptId, hostid, manualinput: serviceName },
        id: 2
      })
    }
  });
}

return items.length > 0 ? items : [{ json: { hostname: '', service_name: '', execute_body: '{}' } }];

const prep    = $('Preparar Execuções').item.json;
const success = $json.result?.response === 'success';
const raw     = (
  $json.result?.value ||
  $json.result?.data ||
  $json.error?.data ||
  $json.error?.message ||
  $json.message ||
  'sem resposta'
).toString();

// Separa status e log do retorno 'Running|LOG:...'
let status = raw;
let logInfo = '';
const logIdx = raw.indexOf('|LOG:');
if (logIdx !== -1) {
  status  = raw.substring(0, logIdx);
  logInfo = raw.substring(logIdx + 5).substring(0, 200);
}

return [{
  json: {
    hostname:     prep.hostname,
    service_name: prep.service_name,
    success,
    output: status,
    log_info: logInfo
  }
}];

const results      = $json.results || [];
const successCount = results.filter(r => r.success).length;
const failCount    = results.length - successCount;
const now          = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });
const lines        = results.map(r => {
  let line = (r.success ? 'OK' : 'FALHA') + ' | ' + r.hostname + ' | ' + r.service_name + ' | ' + r.output;
  if (r.log_info) line += '\n  _Log: ' + r.log_info + '_';
  return line;
}).join('\n\n');

return [{
  json: {
    teams_body: JSON.stringify({
      '@type': 'MessageCard',
      '@context': 'http://schema.org/extensions',
      themeColor: failCount === 0 ? '00B050' : (successCount === 0 ? 'FF0000' : 'FFA500'),
      summary: 'Remediacao em massa: ' + successCount + '/' + results.length + ' servicos reiniciados',
      sections: [{
        activityTitle: 'Remediacao em Massa — ' + now,
        activitySubtitle: successCount + ' reiniciados, ' + failCount + ' falhas de ' + results.length + ' total',
        text: lines,
        markdown: true
      }]
    })
  }
}];
